DO $$ BEGIN CREATE TYPE wsb_payment_status AS ENUM ('PENDING','REQUIRES_ACTION','PAID','FAILED','REFUNDED','PARTIALLY_REFUNDED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,booking_id uuid NOT NULL,customer_id uuid,provider text NOT NULL,provider_payment_id text,purpose text NOT NULL CHECK(purpose IN('DEPOSIT','FULL')),amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL DEFAULT 'MYR',status wsb_payment_status NOT NULL DEFAULT 'PENDING',paid_at timestamptz,refunded_minor bigint NOT NULL DEFAULT 0 CHECK(refunded_minor>=0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id) ON DELETE SET NULL,UNIQUE(tenant_id,id));
CREATE UNIQUE INDEX payments_provider_unique ON payments(tenant_id,provider,provider_payment_id) WHERE provider_payment_id IS NOT NULL;CREATE INDEX payments_booking_idx ON payments(tenant_id,booking_id,created_at DESC);
CREATE TABLE payment_webhook_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,provider text NOT NULL,event_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,provider,event_id));
CREATE TABLE payment_refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,payment_id uuid NOT NULL,provider_refund_id text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>0),status text NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,payment_id) REFERENCES payments(tenant_id,id) ON DELETE CASCADE,UNIQUE(tenant_id,provider_refund_id));
CREATE TABLE payment_artifacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,payment_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('RECEIPT','INVOICE')),number text NOT NULL,content_ref text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,payment_id) REFERENCES payments(tenant_id,id) ON DELETE CASCADE,UNIQUE(tenant_id,kind,number));
CREATE TABLE payment_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,payment_id uuid NOT NULL,event_type text NOT NULL,detail jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,payment_id) REFERENCES payments(tenant_id,id) ON DELETE CASCADE);
